  str_monster_name_2000271_en = "Lumo Ranger",
  str_monster_desc_2900063 = "It is said to be a member of the mysterious organization, Eclipse. Not only does it have powerful attacks, but it also can command the Eclipsites.",
  str_monster_desc_2900141 = "A member of the mysterious organization Eclipse, she and her sister Shire make up the Viper Twins. She'll do whatever it takes to achieve her goal.",
  str_monster_desc_2900181 = "A member of the mysterious organization Eclipse, she and her sister Shelt make up the Viper Twins. Impulsive, she kills enemies with brutality and cruelty.",
  str_monster_desc_2900201 = "It is said to be a member of the mysterious organization, Eclipse. Not only does it have powerful attacks, but it also can command the Eclipsites.",
  str_monster_desc_2900211 = "Violent and gigantic, it's a powerful Eclipsite that seems to bear endless suffering. It's best to stay away from it.",
  str_monster_desc_2900221 = "A fusion of Shelt and Shire. Suffering from incredible pain, it has a strong desire for vengeance, making it a brutal and powerful Eclipsite.",
  str_monster_desc_2900231 = "The creature guarding the Colossus Mantiz that possesses a mysterious ancient technology. Be careful of it.",
  str_monster_desc_2900232 = "The creature guarding the Colossus Mantiz that possesses a mysterious ancient technology. Be careful of it.",
  str_monster_desc_2900241 = "Its destructive force is enough to destroy an entire army. It is said to be a loyal subordinate of a member of the Eclipse organization.",
  str_monster_desc_2900251 = "Extremely agile, it can be likened to a phantom that comes and goes without leaving a single trace, and ordinary means are unlikely to harm it. Also known as the Soul Hunter.",
  str_monster_desc_2000011 = "With fighting skills far surpassing that of Dretchers, it's the Eclipsites' main combat unit. They're also known as Captains and are often seen commanding Dretchers.",
  str_monster_desc_2000071 = "A gigantic Eclipsite responsible for the destruction of various fortifications and is known as a Demolisher.",
  str_monster_desc_2000101 = "Responsible for investigating Aurorian movements, and is also known as a Scout. It usually attacks Aurorians with other Eclipsites.",
  str_monster_desc_2000111 = "Servants of the Evil Eye with strong Skill ATK and Skill RES, they're sometimes found aiding Dretchers.",
  str_monster_desc_2000121 = "An Eclipsite specializing in detecting Aurorian movements. Also known as a Seer, it can sometimes detect across far distances.",
  str_monster_desc_2000131 = "An army of gray reptilian creatures responsible for various basic combat tasks, also known as the Cleaners.",
  str_monster_desc_2000141 = "A short creature carrying a black box that transports the supplies of the Eclipse organization, also known as the Runner.",
  str_monster_desc_2000151 = "These are Eclipsites' fighters. They're powerful in combat and can command the Eclipsites, also known as Officers.",
  str_monster_desc_2000161 = "Has a strong camouflage ability. They often infiltrate Aurorian gatherings to assassinate and are thus known as Assassins.",
  str_monster_desc_2000171 = "One of the \"Materialized Eclipsites.\" Usually in the form of a black bead and is carried by a Shadow or other Eclipsites. It's often released in critical moments of battles to fight.",
  str_monster_desc_2000181 = "One of the \"Materialized Eclipsites.\" Usually in the form of a black bead and is carried by a Shadow or other Eclipsites. It's often released in critical moments of battles to fight.",
  str_monster_desc_2000211 = "They're unsuited for battle, but restore HP of other Eclipsites. Said to have evolved from Shadowgeist, they're sometimes referred to as Healers.",
  str_monster_desc_2000221 = "They're unsuited for battle, but can cause spikes to emerge from the ground, ceiling, and other rock walls to attack passersby! Sometimes referred to as Spikers.",
  str_monster_desc_4000221 = "No combat power.",
  str_monster_desc_2000231 = "Its feet can absorb the surrounding Lumina, becoming extremely powerful. They're said to have evolved from Gloom Ghouls, and are also known as \"Energy Ingesters.\"",
  str_monster_desc_2000241 = "An elite of Evil Eye that has strong observation abilities, making it hard for Aurorians to remain undetected. Also known as Seekers.",
  str_monster_desc_2000251 = "The junior members that form the basis of Lumopolis' military might are numerous and widely active in Patrols.",
  str_monster_desc_2000261 = "They bear the burden of protecting the city round the clock without a word of complaint. Never resting, they're considered the backbone of the Guard.",
  str_monster_desc_2000271 = "They are guards who also serve as scouts. After undergoing special trainings, they possess extremely high mobility, dexterity and agility.",
  str_monster_desc_2000281 = "Guards armed with a superior defense shield. With the ability to endure tough battles, they are the strong walls protecting their comrades.",
  str_monster_desc_2000291 = "Pikers that underwent combat training. Their impactful charge makes them unstoppable on the battlefield.",
  str_monster_desc_2000293 = "Pikers that underwent combat training. Their impactful charge makes them unstoppable on the battlefield.",
  str_monster_desc_2000301 = "Armored Eclipsites from White Night, Black Underbelly. They were previously vicious, but after being captured, they have become a source of entertainment.",
  str_monster_desc_2000302 = "The enhanced version of Armored Eclipsites. Although their armors are more gorgeous, they cannot escape the fate of being a source of entertainment for others.",
  str_monster_desc_2000311 = "It likes to fight Aurorians with its dual blades and is highly skilled. However, it rarely works with other Eclipsites and is also known as a Swordsman.",
  str_monster_desc_2000321 = "Evolved from a fast-moving insect before the war, it moves quickly and is very difficult to deal with. It's also called a Chaser.",
  str_monster_desc_2000341 = "Professional looters who make a living by stealing from ancient civilizations. Since all their energy is used for stealing, their combat abilities are very low, and they'll only escape upon encountering an enemy.",
  str_monster_desc_2000351 = "It is said to be a weaker version of the Crusher. It is thought to be a severely injured Crusher that had evolved after being treated.",
  str_monster_desc_2000411 = "Conditioned by strong energies, some of the Evil Eye Eclipsites have undergone strange mutations.",
  str_monster_desc_2000421 = "Said to be a Shadow Eclipsite mutation, it can increase other Eclipsites' ATK.",
  str_monster_desc_2000431 = "A special Eclipsite created by the ancestors of sandworms. Its Darkflow is very unstable and it explodes upon death.",
  str_monster_desc_2000441 = "Some Eclipsites were affected by strong energy and evolved greatly, providing them with high-resistance towards a particular element.",
  str_monster_desc_2000442 = "This type of Eclipsite has accumulated so much elemental energy that it can affect the elements of their surrounding environment.",
  str_monster_desc_2000451 = "Lumopolis soldiers who were deceived by Gertzurde lost their ability to think and attack after being controlled by the Eclipsites. They would march into battle upon Gertzurde's command.",
  str_monster_desc_2000401 = "Low-level Eclipsites with zero intelligence. They are only capable of obeying their summoner's orders and blocking attacks for them.",
  str_monster_desc_2000491 = "A clone created by high-level Eclipsites possessing special abilities. Looks identical to the original, to the point of causing confusion amongst enemies.",
  str_monster_desc_2000501 = "These Eclipsites have a special hook to pull targets in for group attacks, so be careful.",
  str_monster_desc_2000511 = "This type of Eclipsites possesses a gray crystal that emits a unique ray that in turn disrupts the Lumina flow of the target, making it very difficult to control.",
  str_monster_desc_2000521 = "Mutants spawned after some Eclipsites devour the corpses of other Eclipsites. They can release a special force field that locks up Lumina and makes it impossible to flow.",
  str_monster_desc_2000531 = "Mutated Prober Eclipsites; it's said to have mutated a long-range vision ability with a powerful and accurate method of a long-range attack.",
  str_monster_desc_2000541 = "Mutated Warmonger Eclipsites. They not only have increased combat power but also the special ability to erode Lumina.",
  str_monster_desc_2000551 = "A new type of Eclipsites that appeared in the Secret Territory. They are said to be spawned from the resentful feelings of an ancient race that was exterminated by the Eclipsites. This is the only way to explain the source of the powerful cursing ability that they have mastered.",
  str_monster_desc_2000561 = "Rare Eclipsites. They look like floating Phantoms, move fast, and basically cannot be hit. Also known as Ghosts.",
  str_monster_desc_2000571 = "Witnesses to White Schummer's power explosion. These special Eclipsites are formed from the mixture of her evil and hatred. Unable to move, its dark aura covers the sky, enough to possess a powerful cursing ability.",
  str_monster_desc_2000581 = "Said to be a variant of the Chasm, a low-level Eclipsite. It heeds the summons of a high-level Eclipsite and can self-destruct with great force. The only way to stop this from happening is to eliminate it before it explodes.",
  str_monster_desc_2000601 = "A special Eclipsite that was small and barely visible to the naked eye. Its body has swelled to its current size due to the effect of strong negative emotions.",
  str_monster_desc_2000602 = "An illusion created by Dawn's Luminatics that contains a magical power.",
  str_monster_desc_2000611 = "A special Eclipsite that was small and barely visible to the naked eye. Its body has swelled to its current size due to the effect of strong negative emotions.",
  str_monster_desc_2000701 = "These special Eclipsites have awakened from a deep slumber. They are great in number, but their tactics are quite simple. But be careful, as they have the ability to transform!",
  str_monster_desc_2000702 = "A broken castle buried at the bottom of the sea. Whenever its bell rings, the Desolate Monarch unleashes his wrath upon his enemies.",
  str_monster_desc_2000703 = "This war horse was a mere corpse before it was awakened by the Desolate Monarch. Retaining the strength and loyalty of its past, it attacks all of its master's enemies without question.",
  str_monster_desc_2000704 = "Originally aides to the king, they can perceive passages in the void that others cannot, and then move in quickly to attack.",
  str_monster_desc_2000705 = "Originally a noble, revenge drove her to come to this sea, where she revived the legendary ancient king... However, the dark forces she called upon also devoured her soul, turning her into an Eclipsite.",
  str_monster_desc_2000711 = "These Lost Pawns have gained the power of the void. Although their tactics remain simple, their combat effectiveness has been boosted significantly. They cannot be underestimated.",
  str_monster_desc_2000712 = "A castle that crushes all in its path, its ringing bell becomes every enemy's worst nightmare.",
  str_monster_desc_2000713 = "With a terrifying whinny and hooves that shake the earth, when these fierce riders charge into the fray, the only thing that can stop them is death.",
  str_monster_desc_2000714 = "Words of cruelty and corruption surround... Watch out for attacks from the sides.",
  str_monster_desc_2000715 = "Caroline... Mad with power, she has become one with the void, gaining untold power.",
  str_monster_desc_2000901 = "A new type of Eclipsite rumored to have been created by The Eclipse in order to break through Aurorian defenses. It destroys the terrain around it by self-destructing.",
  str_monster_desc_2001001 = "An Eclipsite that once dwelled in the depths of the Secret Territory, it excels at launching strikes from underground. It is also said to be able to dig underground passages for other Eclipsites.",
  str_monster_desc_2001301 = "The dust has settled and the identity of a familiar yet alien foe is about to be revealed. It is time to prove your resolve.",
  str_monster_desc_2101301 = "Minions of Eclipsites, summoned by high-level Eclipsites.",
  str_monster_desc_4001301 = "Minions of Eclipsites, summoned by high-level Eclipsites.",
  str_monster_desc_2001401 = "The symbiotic tentacles of a Kittypus transfer any incoming damage directly to their host.",
  str_monster_desc_2900271 = "This kind of Eclipsite has undergone a strange mutation. It is said that its combat power is comparable to high-level Eclipsites. It's the head of all armored Eclipsites and has very high HP.",
  str_monster_desc_2900262 = "An Aurorian corrupted by powerful dark forces. It has lost all of its self-consciousness and is extremely dangerous.",
  str_monster_desc_2900263 = "In the past, Eve was driven crazy by the mysterious woman's \"treatment\" that caused her to lose control of her power and the burning down of \"that\" Undercity. Rage and guilt is tearing her heart apart as the tragedy repeats itself over and over again... Quell her anger now.",
  str_monster_desc_2900264 = "A mysterious girl you encountered in Red-Eye Gorge. She \"ordered\" the Eclipsites to take Eve away for an unknown purpose.",
  str_monster_desc_2900281 = "A type of Eclipsite that has little intelligence and has no will of its own. Its purpose is unknown, and one can only guess that it's associated with the Darkover Crisis. Also known as a Darkover Omen.",
  str_monster_desc_2900391 = "Although it moves slowly, it has strong DEF, and is can also launch Abyssal Bombs with overwhelming powers. Also known as a Transporter.",
  str_monster_desc_2900401 = "Originally a Caelestite, but joined Eclipse and possesses tremendous increased power.",
  str_monster_desc_2900402 = "Originally a Caelestite, but joined Eclipse and possesses tremendous increased power.",
  str_monster_desc_2900403 = "Originally a Caelestite, but joined Eclipse and possesses tremendous increased power.",
  str_monster_desc_2900411 = "Originally a member of the Lumopolis Guardians. Won over Shelt, he was willing to destroy Lumopolis for them.",
  str_monster_desc_2900421 = "After Nozard was defeated, its body was retrieved by an unknown organization and experimentally transformed into a terrifying monster.",
  str_monster_desc_2900422 = "A large Eclipsite that resembles a gigantic dragon, lurking in the Blazing Tooth Canyon.",
  str_monster_desc_2900431 = "An ancient giant sandworm has been occupying the site ever since it was destroyed. Recently, after awakening from its long slumber, it began to attack all invading intruders.",
  str_monster_desc_2900441 = "The Eclipse transformed Umbrahulk, making it more powerful. Since then, it has been commissioned by the Eclipse to explore the remains of the Spire and to deal with various contingencies.",
  str_monster_desc_2900451 = "Originally a ghost-like monster, it started to evolve due to the power of Light after entering the land. It can create various illusions with refracted light on the battlefield.",
  str_monster_desc_2900452 = "A portal created by the Eclipsite Phorosion. It's used to hide in and to ambush when it spots an enemy's weakness.",
  str_monster_desc_2900501 = "Evolved from the Siphorb, it absorbed so much Lumina that it's unable to control the color of surrounding light. It can also use its mana to adsorb nearby Aurorians to attack it.",
  str_monster_desc_2900601 = "Mutants spawned after the Eclipse organization's Solmorph absorbed the power of the Spire. They can suddenly release the Lumina it absorbed to deal a powerful killing blow.",
  str_monster_desc_2900611 = "Mutants created by the Eclipse Organization using the remnants of high-level Eclipsites like Phantoms. They have a more powerful splitting ability and can only be destroyed by defeating it and all its clones.",
  str_monster_desc_2900641 = "Several Caracalites combined and mutated into a high-level Eclipsite whose mastery of the Eclipsium is even more powerful. With its special technique of locking up Lumina, it is extremely difficult to deal with.",
  str_monster_desc_2900651 = "It is said that when Tabaad's gene was injected into a powerful Eclipsite, a Tabaad-like high-level Eclipsite emerges with more powerful abilities and unquestioning obedience.",
  str_monster_desc_2900661 = "Another of Forsakin's new toys. In contrast to the previous Boredom, it possesses a terrifying ability that can erode Lumina on top of its great power. Should never be taken lightly.",
  str_monster_desc_2900671 = "After the seeds inside her body has achieved parasitic growth, her form that has absorbed huge amounts of energy has become completely different from the past. Even her appearance has changed subtly.",
  str_monster_desc_2900681 = "Mutated Flicker Eclipsites. Extremely agile, it can be likened to a phantom that comes and goes without leaving a single trace, and ordinary means are unlikely to harm it.",
  str_monster_desc_2900701 = "Robot left behind by an ancient civilization. Uniquely designed, it can continue to work even if it is partially destroyed. It's extremely difficult to deal with.",
  str_monster_desc_2900711 = "Robot appeared after the split of T-1024. It will find other T-256s first and try to form another T-1024.",
  str_monster_desc_2910711 = "A functional droid with unknown origins. Its offensive capabilities are not to be underestimated.",
  str_monster_desc_29107141 = "\"Beep! Beep!\"",
  str_monster_desc_29107111 = "\"Beep! Bzz!\"",
  str_monster_desc_2800241 = "\"What are you looking at? Don't expect to find any information about me from here. Neither the Aurorians nor the Caelestites can understand the HIGHER level of a pursuit...\"",
  str_monster_desc_2900801 = "An ancient king who was buried deep in the ocean for eons. Awakened by the Deceptive Queen, he has now vowed to trap his enemies in the void forever.",
  str_monster_desc_2900811 = "The enraged ancient king controls and toys with all and any intruders until death finally claims them.",
  str_monster_desc_2900911 = "Rumored to be high-level Eclipsites previously engaged in several fierce battles. Unknown in number and possessing the rare ability to fly, they have now awakened from their slumber and are set to plunge the Aurorians into an all-new nightmare.",
  str_monster_desc_2900912 = "This Eclipsite follows Hylingerr and can aid it in battle.",
  str_monster_desc_2901001 = "Originally a noble of Lumopolis, after being banished from the city, his resentment for his former nation festered, to the point where he defected to the Eclipse and attempted to overthrow the Lumopolis leadership. When his plan failed, he descended even deeper into insanity, his mounting hatred fueling his power...",
  str_monster_desc_2901101 = "Unable to overcome his fear, and desperate to realize his ambition, he undergoes a dangerous temporary transformation without a second thought, mutating into this terrifying creature.",
  str_monster_desc_2901201 = "An ancient hero who became an Eclipsite to fight against them. He has now become a senseless monster.",
  str_monster_desc_2901300 = "Enigmatic Eclipsite of unknown origin, whose presence does not seem to conform to the reality you know.",
  str_monster_desc_2901301 = "The dust has settled and the identity of a familiar yet alien foe is about to be revealed. It is time to prove your resolve.",
  str_monster_desc_2901401 = "A special companion of Gretel. Generally quiet and placid, but known to go berserk in battle. Approach with caution.",
  str_monster_desc_2901501 = "A special companion of Gretel. Playful and energetic, it particularly enjoys fighting against a group of enemies.",
  str_monster_desc_2901601 = "A special companion of Gretel. It has a pair of extremely strong legs that can repel any enemy.",
  str_monster_desc_2901701 = "A special companion of Gretel. It resembles a cat with many legs... It's cute, yet somehow disturbing.",
  str_monster_desc_2901801 = "The inhabitants of the lost city and the offspring of the Illumina explorer—Seamus. They seemed to think of themselves as the masters of this place.",
  str_monster_desc_2901901 = "Former chief of the Wisp who's dedicated to fighting Cloud Island invaders.",
  str_monster_desc_2901911 = "The frenzied Nagi will attack anyone she perceives as an intruder.",
  str_monster_desc_2902001 = "A tyrant who came from another Far East island to rule Cloud Island, and he'll do anything to declare sovereignty over it.",
  str_monster_desc_2902101 = "Due to his obsessiveness, he turned into a hideous man and vowed to eliminate all who resisted.",
  str_monster_desc_2902201 = "A powerful Eclipsite that lived alone in the ruins for many years. Completely insane, it attacks all outsiders.",
  str_monster_desc_2902202 = "A former Illumina soldier who turned into an Eclipsite under the Darkflow's influence. Hatred consumed all his sanity and stole all his former glory.",
  str_monster_desc_2902301 = "The AI in the underground base of Eraveil that has been guarding the base for thousands of years and is responsible for clearing out all invading enemies.",
  str_monster_desc_2902401 = "The AI in the underground base of Eraveil who looks big and heavy, it's Claudia's friend.",
  str_monster_desc_2902501 = "The Andersen's gold medal butler who leaves no stains, trash or vermin unattended.",
  str_monster_desc_2902601 = "It's said to be the Phantom's \"brother\" in Eternal Night. It's able to use different tactics according to the time of the day and is extremely difficult to deal with.",
  str_monster_desc_2902701 = "\"What are you looking at? Don't expect to find any information about me from here. Neither the Aurorians nor the Caelestites can understand the HIGHER level of a pursuit...\"",
  str_monster_ability_2900063 = "Attacks front targets with its giant claws and can fly into the air to bomb specific areas on the ground.",
  str_monster_ability_2900141 = "Skilled in melee attacks, its attacks will stun the target with the ability to summon the Gloom Ghoul. After it turns Rabid, its normal attacks become double attacks with greatly enhanced skill range, and it can summon Shadowgeist and Gloom Ghoul at the same time.",
  str_monster_ability_2900142 = "Excelling at melee attacks, has the ability to summon other Eclipsites. While in Rabid mode, it restores 20% of its maximum health; after Rabid mode ends, its normal attacks can strike twice, and its skill range is greatly increased.",
  str_monster_ability_2900181 = "Skilled in ranged attacks which will stun the target and summon the Shadowgeist. When Rabid, her normal attacks hit twice with greatly enhanced skill range, and she can summon Shadowgeist and Gloom Ghoul at the same time.",
  str_monster_ability_2900182 = "Excelling at long-range combat, its attacks are capable of knocking back targets. Has the ability to summon other Eclipsites. While in Rabid mode, restores 20% of its maximum health; after Rabid mode ends, its normal attacks can strike twice, and its skill range is greatly increased.",
  str_monster_ability_2900201 = "It's good at using its large body to attack targets in front of it. It burrows into the ground and damages nearby targets upon emerging.",
  str_monster_ability_2900211 = "Its melee attack is accompanied with a knockback, and it has the ability to summon Pebbles for attacking. Hit targets will be knocked back, and knocked back areas will spawn new Pebbles. It can also launch a full-screen attack, and the damage dealt is determined by the number of Pebbles.",
  str_monster_ability_2900221 = "Its normal attack comes with a knockback. It can convert combat area into Lumina of its own element and unleash a wide range of attacks based on its own element: Fire - Large area damage with Burning effects, Thunder - Full-screen damage with random Spikepest.",
  str_monster_ability_2900231 = "Philex's melee attack comes with a knockback, and his skill ATK stuns targets.",
  str_monster_ability_2900232 = "Vani can use Energy to strike from a distance and recover HP to Philex.",
  str_monster_ability_2900241 = "It throws Incendiary Rounds at the battle zone, causing passing units to be inflicted with Burns. It can charge at a target and stun them when hit, using sword aura to attack two rows of targets in front of it.",
  str_monster_ability_2900251 = "It deals a cross-shaped area attack and will summon a clone to fight alongside it. After cloning, it will absorb the former clone's HP to restore HP to itself. When its HP is less than 50%, its normal attacks will turn into double attacks; area attacks will turn into full-screen attacks.",
  str_monster_ability_2000011 = "Eclipsites' main combat unit, skilled in close combat with claws.",
  str_monster_ability_2000071 = "A large-sized Eclipsite responsible for the destruction of various fortifications and is more than capable of demolishing buildings.",
  str_monster_ability_2000101 = "An Eclipsites' scout that is able to use the light emitted from its mouth to attack enemies from a distance.",
  str_monster_ability_2000111 = "Better known for its use of barriers to resist attacks.",
  str_monster_ability_2000121 = "An Eclipsite with low-level summoning abilities. Unable to move on its own and fights by summoning Dretcher.",
  str_monster_ability_20001211 = "An Eclipsite with low-level summoning abilities. Unable to move on its own and fights by summoning Eclipsites.",
  str_monster_ability_20001221 = "An Eclipsite with low-level summoning abilities. Unable to move on its own and fights by summoning Spellhounds.",
  str_monster_ability_20001231 = "An Eclipsite with low-level summoning abilities. Unable to move on its own and fights by summoning Darkwasp.",
  str_monster_ability_20001241 = "An Eclipsite with low-level summoning abilities. Unable to move on its own and fights by summoning Dreadblades.",
  str_monster_ability_20001251 = "An Eclipsite with low-level summoning abilities. Unable to move on its own and fights by summoning Slashers.",
  str_monster_ability_20001261 = "An Eclipsite with basic summoning abilities. Unable to move on its own and fights by summoning Prober.",
  str_monster_ability_2000131 = "A low-level Eclipsite, only capable of basic attacks based on instinct.",
  str_monster_ability_2000141 = "An Eclipsite with average ATK that's responsible for gathering supplies.",
  str_monster_ability_2000151 = "Adept at using its two massive fists to tussle. Its Hammer Bash ability deals ground damage and inflicts Stun on targets.",
  str_monster_ability_2000161 = "Use its spear to attack the target and gain the ability to summon Shadowgeist.",
  str_monster_ability_2000171 = "Materialized Eclipsites Type II: Healer Eclipsites. Usually in the form of a black bead and is able to heal other Eclipsites when released.",
  str_monster_ability_2000181 = "Materialized Eclipsites Type I: Ranged Eclipsites. Usually in the form of a black bead. Able to engage in battle when released, but its fighting power is relatively weak.",
  str_monster_ability_2000211 = "An Eclipsite with the ability to heal, mainly responsible for restoring HP of other Eclipsites.",
  str_monster_ability_2000221 = "Unsuited for battle, but it can cause spikes to emerge from the ground to attack passersby.",
  str_monster_ability_4000221 = "Normally, monsters of this kind use spikes on the ground to attack passersby. But this particular one's ability seems to be different in some way.",
  str_monster_ability_2000231 = "A range Eclipsite whose main combat skill is to strengthen itself by absorbing Lumina. Adept at long-range attacks and while its original battle power lacking, after absorbing Lumina, its battle power is greatly improved.",
  str_monster_ability_2000241 = "An Eclipsite with intermediate summoning abilities. Unable to move on its own, it fights by summoning Probers that possess ranged attack abilities.",
  str_monster_ability_20002411 = "An Eclipsite with powerful summoning abilities. Can summon various types of Eclipsites to fight.",
  str_monster_ability_20002421 = "An Eclipsite with intermediate summoning abilities. Fights by summoning Dreadblades that possess powerful melee abilities.",
  str_monster_ability_20002422 = "An Eclipsite with intermediate summoning abilities. Fights by summoning Dreadblades that possess powerful melee abilities and Spellhounds with incredible defensive capabilities.",
  str_monster_ability_20002423 = "An Eclipsite with intermediate summoning abilities. It fights by summoning Dreadblades that possess powerful melee abilities and Vinesmark that launches deadly ranged attacks.",
  str_monster_ability_2000251 = "Junior members of the Lumopolis military base. Large in numbers, their main combat mode is the use of equipped weapons for long-range attacks.",
  str_monster_ability_2000261 = "Lumopolis mechanical guards. When encountering enemies, they fight by creating longsword soldiers.",
  str_monster_ability_2000271 = "Elite Lumopolis scouts that will instantly move to another location after attacking their target. Their mobility and dexterity make them a hard target to hit in regular combat.",
  str_monster_ability_2000281 = "Shield-armed guards with superior DEF. The shield in their arms serves not only as a means of defense, but also as a melee weapon.",
  str_monster_ability_2000291 = "Pikers that underwent combat training. They have a strong will to fight and possess strong melee skills.",
  str_monster_ability_2000293 = "Pikers that underwent combat training. They have a strong will to fight and possess strong melee skills.",
  str_monster_ability_2000301 = "Normal carrier Eclipsites. Usually transport light shipments of Nightium. Defeat them to get the money.",
  str_monster_ability_2000302 = "Enhanced carrier Eclipsites. Usually transport big shipments of Nightium. Defeat them to get the money.",
  str_monster_ability_2000311 = "A newly emerged Eclipsite that may have evolved from other Eclipsites. It's good at dual wielding blades and launches double attacks on its target when confronted.",
  str_monster_ability_2000321 = "A rapid moving insect-type Eclipsite, ordered to pursue and hunt down its targets at close quarters.",
  str_monster_ability_2000341 = "A large number of bandits who are skilled at escaping.",
  str_monster_ability_2000351 = "A powerful Eclipsite that can knock targets back with its attacks.",
  str_monster_ability_2000411 = "A mutant Eclipsite that specializes in ranged attacks. When its element is Fire, it can summon Burning Rain to burn targets that are hit. When its element is Thunder, it can summon Lightning Power to paralyze targets hit.",
  str_monster_ability_2000421 = "Specializes in ranged attacks and grants buffs to nearby Eclipsites in battle.",
  str_monster_ability_2000431 = "Specializes in melee combat. When it's on the verge of death, it'll move towards players and detonate, dealing damage to all surrounding targets.",
  str_monster_ability_2000441 = "Attacks target with melee attacks. The effects of Aurorian attacks that don't counter its element will be greatly reduced.",
  str_monster_ability_2000442 = "Launches melee attacks against its target, and converts all tiles along its movement path into tiles of the same element as itself.",
  str_monster_ability_2000451 = "Inflicts debuffs on its enemies.",
  str_monster_ability_2000501 = "Can pull distant targets to self and deal huge damage to targets within 1 surrounding cluster.",
  str_monster_ability_2000511 = "Attack Range is very small. However, its attack causes Aurorian to lose energy, which in turn increases the number of the Active Skill's cooldown rounds.",
  str_monster_ability_2000521 = "Can lock tile elements. When hitting a target, tile elements around the target will be locked. After moving, will lock tile elements around itself.",
  str_monster_ability_2000531 = "Eclipsites that are extremely good at attacking from a distance. The farther the attacked target is from the Vinesmark, the more damage the target will take.",
  str_monster_ability_2000541 = "Doomskull's powerful attacks can crush tiles within a large area range.",
  str_monster_ability_2000551 = "Rare Eclipsites with the ability to curse. It will release a curse on the target. The cursed Aurorian cannot use Active Skills, move, or be set as the Captain for several rounds.",
  str_monster_ability_2000561 = "A long-ranged hunter that changes its position before attacking each round.",
  str_monster_ability_2000571 = "Daemons controlled by Schummer. They will intervene with the Aurorian deployment. If Aurora Time cannot be triggered within several rounds, the Aurorians will be plunged into darkness.",
  str_monster_ability_2000581 = "An Eclipsite summoned by Formless, this mindless monster launches suicide attacks on its enemies. Explodes if it is not destroyed within a certain number of rounds, destroying its current location.",
  str_monster_ability_2000582 = "An Eclipsite summoned by Formless, this mindless monster launches suicide attacks on its enemies. Explodes if it is not destroyed within a certain number of rounds, summoning an Alarming Area.",
  str_monster_ability_2000601 = "An Eclipsite with no combat ability, but it can attach to an Eclipsite within 1 surrounding cluster of itself. After attaching itself, it provides the Eclipsite with a Shield and enhances its attacks.",
  str_monster_ability_2000602 = "This attaches itself to Dawn and recovers her HP when it is within 1 surrounding cluster of Dawn.",
  str_monster_ability_2000611 = "An Eclipsite with no combat ability, but it can attach itself to an Aurorian within 1 surrounding cluster of itself. Once attached, it will continue to reduce the Aurorian's sanity value.",
  str_monster_ability_2000701 = "After moving, deals damage in 4 tiles in a cross shape around it. Upon reaching the edge of the Alchemy Board, they will be promoted to either an Enraged Rook, Fallen Knight, Eclipse Bishop, or Deceptive Queen, according to their order of arrival.",
  str_monster_ability_2000702 = "Can only move horizontally or vertically from its own position. After moving, it deals damage to targets within 1 surrounding cluster. When ramming into a target while moving, it will deal higher damage to this target and knock them back to the edge of the board.",
  str_monster_ability_2000703 = "Can only jump diagonally. After landing, deals damage in the 4 surrounding tiles in a cross shape. If there is a target at its landing point, it deals severe damage to the target and stuns them, while knocking the target back.",
  str_monster_ability_2000704 = "Can only move diagonally. Deals damage to targets within its maximum cross-shaped range.",
  str_monster_ability_2000705 = "Deals damage equal to a percentage of the target's maximum HP to targets within its maximum radial-shaped range.",
  str_monster_ability_2000711 = "After moving, deals damage in 4 tiles in a cross shape around. Upon reaching the edge of the Alchemy Board, they will be promoted to either an Enraged Rook - RAM, Fallen Knight - CHARGE, Eclipse Bishop - EX, or Deceptive Queen, according to their order of arrival.",
  str_monster_ability_2000712 = "Can only move horizontally or vertically from its own position. After moving, it deals damage to targets within 2 surrounding clusters. When ramming into a target while moving, it will deal higher damage to this target and knock them back to the edge of the board.",
  str_monster_ability_2000713 = "Can only jump diagonally. After landing, deals damage to 1 surrounding cluster. If there is a target at its landing point, it deals severe damage to the target and stuns them, while knocking them back.",
  str_monster_ability_2000714 = "Can only move diagonally. Deals damage to targets within its maximum cross-shaped range and reduces their DEF.",
  str_monster_ability_2000715 = "Deals damage equal to a percentage of the target's maximum HP to targets within its maximum radial-shaped range. If there are no targets in the 8 directions around it, it gains a defensive barrier.",
  str_monster_ability_2000901 = "Self-destructs after counting down to zero, destroying the tile at its current location and rendering it unusable.",
  str_monster_ability_2001001 = [[
Excels at utilizing damaged terrain and possesses the ability to deal heavy damage to units around damaged tiles.
When Aurorians pass through damaged tiles, their combo counter will not increase.]],
  str_monster_ability_2001301 = "With strong skill ATK and normally concealed in the battleground. It can not be attacked unless it reveals itself during Aurora Time.",
  str_monster_ability_2001341 = "Deals a lot of damage and is invincible while on Green tiles.",
  str_monster_ability_2101301 = "Eclipsite Minion does not attack and is normally concealed in the battleground. It can not be attacked unless it reveals itself during Aurora Time.",
  str_monster_ability_4001301 = "Deals a lot of damage.",
  str_monster_ability_2001401 = "Sensitive and meek, it will dodge Aurorian attacks at all costs.",
  str_monster_ability_2900271 = "An advanced armored Eclipsite that is able to use full-screen range skills.",
  str_monster_ability_2900262 = "Unable to move on its own, but it has a wide range of attack. It can absorb dark matter and turn them into a barrier. It can also attack and knockback three rows of enemies in front of it.",
  str_monster_ability_2900263 = "Unable to move on its own, but it has a wide range of attack. It can absorb dark matter and turn them into a barrier. It can also attack and knockback three rows of enemies in front of it.",
  str_monster_ability_2900264 = "Deals damage within 2 surrounding clusters and enemies in the full-screen. Can transform into a Dawn Sprite to recover her HP.",
  str_monster_ability_2900281 = "It can summon a beacon and restore the beacon's HP while gaining damage reduction based on the number of beacons around it. Its skills have a cross-shaped range attack and its chargeable skill's damage and range are based on the number of beacons.",
  str_monster_ability_2900391 = "Unable to move on its own and is only vulnerable to Bomb Damage. It can summon bombs, and after fully charged, it will continuously to summon bombs and release wide area Damage Skill.",
  str_monster_ability_2900401 = "Resistant to physical attacks and can resist Normal Attack damage. Deals damage to forward targets and can launch full-screen attacks. Able to summon Lightning Crystals.",
  str_monster_ability_2900402 = "Resistant to Normal Attack damage. Deals damage to targets in a cross-shaped or full-screen range, summoning thunderbolts upon specific areas periodically. Deals continuous full-screen damage after turning Rabid.",
  str_monster_ability_2900403 = "It's good at ranged and AOE attacks and can synchronize its HP. The lowest HP Schummer will synchronize its HP with the highest HP Schummer on the battlefield, up to 30% per regeneration.",
  str_monster_ability_2900411 = "Summons reinforcements in battle. Attack range is now the full field, and attacks will add a debuff to enemies hit that lowers their defense. Enraged normal attacks will hit twice.",
  str_monster_ability_2900421 = "Can attack specific areas and summon Spellhounds for support, dealing damage to targets in front or across the whole screen.",
  str_monster_ability_2900422 = "Deals damage to targets in front of it or across the whole screen and knocks enemy units back. Able to summon Spikepests.",
  str_monster_ability_2900431 = "It's good at using its large body to attack targets in front. It burrows into the ground and damages nearby targets upon emerging. It also can summon Burst Bugs.",
  str_monster_ability_2900441 = "Its normal attack comes with a knockback, and it can summon a Duplicate Crystal to create 1 elemental Pebble per round. It can consume all Pebbles to launch an attack on the target, which damage is determined by the number of Pebbles.",
  str_monster_ability_2900451 = "Will hide in the Lumiwall farthest from the player; attacks can change the element of the tile on its attack path.",
  str_monster_ability_2920451 = "Creates illusions around targets after ramming them. Each Lumiwall reduces the damage taken by the Phorosion, as well as its ATK; while Awakened, Lumiwalls create new illusions every round.",
  str_monster_ability_2900452 = "Will hide in the Lumiwall farthest from the player; attacks can change the element of the tile on its attack path.",
  str_monster_ability_2900501 = "Possesses the ability to change the Alchemy Board's Tile color. Targets hit by its skill will be pulled towards it.",
  str_monster_ability_2900601 = "Skilled in wide-range attacks. It can pull distant targets to itself, and can change the tile elements of targets hit and tiles in a wide range around itself.",
  str_monster_ability_2900611 = "Unable to move but skilled in cross-shaped and wide-range attacks; attacks will cause the Aurorians to lose energy, which in turn increases the number of cooldown rounds of Active Skills; it will split when it dies.",
  str_monster_ability_2900641 = "Skilled in wide-range attacks. Locks the elements of tiles around it after it moves, and possesses the ability to counterattack, locking the elements of tiles in 1 surrounding cluster around Aurorians each time they use an Active Skill.",
  str_monster_ability_2900651 = "Skilled in wide-range attacks; ultra-large range attacks deal more damage to targets further away; can summon Vinesmarks for support.",
  str_monster_ability_2900661 = "Shatterblast will crush all tiles in the field. This attack can knock the target back. Can counterattack. It will crush 2 random tiles on the field every time an Aurorian releases an Active Skill.",
  str_monster_ability_2900662 = "Shatterblast will crush all tiles in the field. This attack can knock back the target.",
  str_monster_ability_2900671 = [[
Can use cross-shaped or full-screen attacks and summon thunderbolts. When enraged, it gains the ability to knock targets back significantly and deal full-screen damage and wide-range damage.
Note: When all of Schummer's Daemons are activated, Schummer will cast a full-screen skill that annihilates all Aurorians.]],
  str_monster_ability_2900681 = "Summons Nonentities that can self-destruct. Possesses a powerful teleportation ability and can teleport far away from the player, attacking from the edges of the Alchemy Board.",
  str_monster_ability_2900701 = "Attacks cause a knockback effect on the target; it will reflect damage if attacked while it's defending; possesses a strong recovery power; summons a T256 upon death.",
  str_monster_ability_2900711 = "An ancient mechanical construct that appeared after T-1024 divided. Possesses innate long-ranged attack capability.",
  str_monster_ability_2910711 = "A functional droid with unknown origins and capable of making normal ranged attack.",
  str_monster_ability_29107141 = "\"Beep! Beep!\"",
  str_monster_ability_29107111 = "\"Beep! Bzz!\"",
  str_monster_ability_2800241 = "It seems to be a very powerful opponent with hidden power that will knock the target back every round.",
  str_monster_ability_2900801 = "Capable of commanding Lost Pawns to deal damage to targets in 1 surrounding cluster. Can knock back targets around itself and launch full-screen attacks.",
  str_monster_ability_2900811 = "Capable of commanding Lost Pawns to deal damage to targets in 1 surrounding cluster. Can knock back targets around itself and launch full-screen attacks.",
  str_monster_ability_2900911 = "Can deal damage to targets in a large area in front of it, and has the ability to track targets.",
  str_monster_ability_29009111 = "Can deal damage to targets in a large area in front of it, and has the ability to track targets. Can summon Tentaclaws that can influence Aurorians' Sanity.",
  str_monster_ability_2900912 = "Attacks wherever the player was located in the previous round. Its area attacks deal damage to targets and knock them back. This monster will resurrect at its location several rounds after dying.",
  str_monster_ability_2901001 = "Attacks and knocks back enemies around damaged tiles. Charges at enemy units within its attack range and repels them. Can damage tiles repeatedly teleporting.",
  str_monster_ability_2901101 = "Can attack Aurorians from range, and possesses the ability to control Eclipsites.",
  str_monster_ability_2901201 = "Possesses strange and terrifying power. When Claymore's HP falls to a certain amount, will ______.",
  str_monster_ability_2901300 = "It has a powerful damage-reducing ability. Can only deal damage to it during Aurora Time.",
  str_monster_ability_2901301 = "It has a powerful damage-reducing ability. Can only deal damage to it during Aurora Time. Able to summon Fearmonger Minions with strong ATK to assist it.",
  str_monster_ability_2901341 = "Has extremely strong DEF and can summon Fearmonger Minions with strong ATK to assist it. However, the Fearmonger's DEF also decreases when Fearmonger Minions die.",
  str_monster_ability_2901401 = "Attacks summon a special kind of Spikepest that cannot be slain using board-wiping attacks. If players stand too close when attacking, their damage against mobs is significantly reduced.",
  str_monster_ability_2901501 = "Excretes a poisonous substance, so that a portion of its melee attacks will Paralyze the player. If players stand too close when attacking, their damage against mobs is significantly reduced.",
  str_monster_ability_2901601 = "Ironstomp marches heavily across the battlefield, dealing devastating damage to any tiles in its path.",
  str_monster_ability_2901701 = "Kittypus unleashes its tentacles, dealing massive damage to Aurorians. (Remember: Kittypus' tentaclaws transfer all incoming damage to their host!)",
  str_monster_ability_2901801 = "Keeps a distance from targets and is able to summon and control traps to aid herself in combat.",
  str_monster_ability_2901901 = "Able to make different tactical choices based on the distance from Aurorians.",
  str_monster_ability_2901911 = "When frenzied, Castellan's swordsmanship is enhanced and deals a massive amount of damage.",
  str_monster_ability_2902001 = "Cunning and treacherous, he's skilled at ranged attacks. When the enemy gets close, he runs away and leaves a shadow behind. He can also conjure up a specific number of ghosts to assist in battle every round.",
  str_monster_ability_2902101 = "Conjure up a large number of ghosts and unleash different powerful skills based on the distance between Aurorians and the enemy in each round. When Fujikumo Nobutora - Devour kills a ghost, it restores HP for yourself.",
  str_monster_ability_2902201 = "A horrific Eclipsite that accumulates bruise value when sustaining damage during the day. Able to counterattack, it inflicts DMG on nearby targets and restores HP according to its bruise value every time an Aurorian releases an Active Skill. Its powers seem to enhance after nightfall!",
  str_monster_ability_2902202 = "Accumulates bruise value when sustaining damage during the day. Able to counterattack, Helios inflicts DMG on nearby targets and restores HP according to his bruise value every time an Aurorian releases an Active Skill. He transforms into a more powerful Eclipsite after nightfall, temporarily losing bruise skills, but is instead able to move 3 times each round.",
  str_monster_ability_2902301 = "Able to move on the field ingeniously and resist Aurorian's normal attacks as well as most ground damage using the obstacles. When the obstacle is destroyed, runs to the nearby obstacles quickly. The skills Claudia casts nearby obstacles will be more powerful than when they are cast on the ground.",
  str_monster_ability_2902401 = "Possesses strong DEF that makes Claudia almost unbeatable on the battlefield.",
  str_monster_ability_2902501 = "Minos will switch between two states based on his stack of Marks. When he is in the Mortal State and the Minotaur State, he will reset all the tiles he passed through to enhanced and weakened tiles respectively. The more enhanced tiles there are on the board, the more powerful Minos will become.",
  str_monster_ability_2902601 = "It's able to accumulate Bruise when taking damage during the day, converting it to HP at night while becoming a more powerful Eclipsite that's able to deal damage to all enemies on screen.",
  str_monster_ability_2902701 = "Seems to be a very powerful opponent that can knock the target back every round and summon Eclipsites to assist in battle. Can even control the generation of the Dark Region.",
  str_monster_name_2910271 = "Coagulating Goldor",
  str_monster_ability_2910271 = "Not only does it possess a full-screen attack, but it also boasts heightened defense. After taking a certain amount of damage each round, no further damage can be dealt to it.",
  str_monster_name_2100111 = "Spellhound Warden",
  str_monster_ability_2100111 = "A mutated Spellhound with a stronger barrier than average Spellhounds, granting it greater resistance to damage.",
  str_monster_name_2910211 = "Bloodthirsty Umbrahulk",
  str_monster_ability_2910211 = "A bloodthirsty Eclipsite that recovers HP after attacking targets. Its melee attack is accompanied by a knockback effect, and it can summon Pebbles. It can also launch a full-screen attack, dealing damage based on the number of Pebbles summoned.",
  str_monster_name_2910701 = "Modified T1024",
  str_monster_ability_2910701 = "After modification, the T1024 can repair itself by attacking. Attacks cause a knockback effect on the target; it will reflect damage if attacked while it's defending; possesses a strong recovery power; summons a T256 upon death.",
  str_monster_name_2910501 = "Shifting Solmorph",
  str_monster_name_2920501 = "Evolved Solmorph",
  str_monster_name_2910601 = "Shadowborn Solfall",
  str_monster_name_2910451 = "Umbral Phorosion",
  str_monster_ability_2910451 = "Will hide in the Lumiwall farthest from the player. Attacks can change the element of the tiles on its attack path. Break 3 Lumiwalls to make it appear.",
  str_monster_name_2910403 = "Grievous Schummer",
  str_monster_ability_2910403 = "Skilled at ranged and AoE attacks, and can synchronize its HP. Synchronize: The lowest HP Schummer will synchronize its HP with the highest HP Schummer on the battlefield, restoring its HP.",
  str_monster_name_2920403 = "Shattered Schummer",
  str_monster_ability_2920403 = "Restores HP when attacked by Aurorians with countering elements. Skilled at ranged and AoE attacks, and can synchronize its HP. Synchronize: The lowest HP Schummer will synchronize its HP with the highest HP Schummer on the battlefield, restoring its HP.",
  str_monster_name_2910411 = "Rueful Gertzurde",
  str_monster_ability_2910411 = "When Gertzurde is in Rage mode, normal attacks will hit twice and summon reinforcements in battle. Attacks will add an attack and defense debuff to the enemies hit. Gertzurde's attack range is now the full grid.",
  str_monster_name_2910441 = "Ferocious Herkeros",
  str_monster_name_2910611 = "Augmented Deathless",
  str_monster_ability_2910611 = "Unable to move but skilled in cross-shaped and wide-range attacks; attacks will cause the Aurorians to lose energy, which in turn increases the number of cooldown rounds of Active Skills; it will split when it dies. Each time a Deathless dies, the remaining Deathless are restored to full HP.",
  str_monster_name_2910252 = "Berserk Phantom",
  str_monster_ability_2910252 = "Gains a certain amount of ATK per round, and after taking a certain amount of damage each round, no further damage can be dealt to it. Launches a cross-shaped area attack and summons clones to fight alongside it. After cloning, it will absorb the former clone's HP to restore HP to itself. When its HP is less than 50%, its normal attacks will become double attacks, and area attacks will become full-screen attacks.",
  str_monster_name_2100241 = "Ravenous Croweye",
  str_monster_ability_2100241 = "An Eclipsite with medium-level summoning abilities. Unable to move on its own and fights by summoning Flatlines.",
  str_monster_name_2910431 = "Earthsplitting Mara Sol",
  str_monster_ability_2910431 = "Excels at using its large body to attack targets in front of it. It burrows into the ground and damages nearby targets upon emerging, while also summoning Burst Bugs.",
  str_monster_name_2910141 = "Rabid Shelt",
  str_monster_ability_2910141 = "Skilled in melee attacks, it can launch two normal attacks each round. Its attacks stun targets hit, and it can also summon Shadowgeist and Gloom Ghouls. Possesses the ability to counterattack, summoning Shadowgeist or Gloom Ghouls to assist in battle whenever Aurorians use skills.",
  str_monster_name_2910182 = "Rabid Shire",
  str_monster_ability_2910182 = "Skilled in ranged attacks, it can launch two normal attacks each round. Its attacks knock back targets hit, and it can also summon Shadowgeist and Gloom Ghouls. Possesses the ability to counterattack, summoning Shadowgeist or Gloom Ghouls to assist in battle whenever Aurorians use skills.",
  str_monster_name_2910231 = "Bloodthirsty Philex",
  str_monster_ability_2910231 = "A bloodthirsty Eclipsite that recovers HP after attacking targets. Its melee attacks inflict a knockback effect, and its attack skills stun targets.",
  str_monster_name_2910232 = "Analeptic Vani",
  str_monster_ability_2910232 = "A bloodthirsty Eclipsite that recovers HP after attacking targets. Can use Energy to strike from a distance and restore HP to Philex.",
  str_monster_name_2910221 = "Boredom Splitter",
  str_monster_ability_2910221 = "Ignores damage from Aurorians with the same element as itself, and restores HP when attacked by Aurorians countered by this element. Its normal attacks inflict a knockback effect. Unleashes a wide range of attacks based on its element: Fire - Large area damage with Burn effects, Thunder - Full-screen damage that randomly generates Spikepests.",
  str_monster_name_2100311 = "Augean Annihilator",
  str_monster_ability_2100311 = "Can attack its target four times. Immune to skill damage. Movement Counter: Every time Aurorians use an Active Skill this round, the Augean Annihilator's movement range increases by 2 in the next round.",
  str_monster_name_21003111 = "Augean",
  str_monster_ability_21003111 = "Immune to skill damage.",
  str_monster_ability_21003112 = "Movement Counter: Every time Aurorians use an Active Skill this round, the Augean Annihilator's movement range increases by +2 in the next round.",
  str_monster_name_21003111_en = "Augean",
  str_monster_ability_21003111_en = "Immune to skill damage.",
  str_monster_name_2250281 = "Enslaved Dark Summoner",
  str_monster_name_9100161 = "Necrotic Shadow",
  str_monster_desc_9100161 = "When certain Shadows enter the Spire, the special power of light that exists here causes them to transform, heightening their ability to hunt their prey. It is for this reason that they are deployed specifically to deal with explorers who dare to enter the Spire.",
  str_monster_ability_9100161 = "Uses its spear to attack targets. Possesses the ability to summon Darkwasps.",
  str_monster_name_5400231 = "Bloodthirsty Philex",
  str_monster_ability_5400231 = "A bloodthirsty Eclipsite that recovers HP after attacking targets. Its melee attacks knock back targets, and its skill attacks stun targets.",
  str_monster_name_5400232 = "Analeptic Vani",
  str_monster_ability_5400232 = "A bloodthirsty Eclipsite that recovers HP after attacking targets. Can use Energy to strike from a distance and restore HP to Philex.",
  str_monster_name_20005011 = "Rhein",
  str_monster_desc_20005011 = "In order to escape Lumopolis's punishment, he used his enhancers to transform himself from a former guild leader into an evil monster.",
  str_monster_ability_20005011 = "The mutated Rhein can pull over distant targets to his immediate vicinity to launch attacks and Spikepests at targets within 1 surrounding cluster.",
  str_monster_name_20002441 = "Lachon Hermes",
  str_monster_desc_20002441 = "Through a desire for power and long life, he degenerated into an Eclipse lackey, finally becoming the monstrosity you see before you.",
  str_monster_ability_20002441 = "The mutated Lachon gains an advanced summoning ability. He cannot move and fights by summoning groups of Eclipsites.",
  str_monster_name_3900281 = "Nefarious Dark Summoner",
