  str_monster_ability_80063801 = "Deals damage twice after using its incredible agility to distance itself from the target.",
  str_monster_ability_2910242 = "Excels at using large area attacks; ultra-large range attacks deal more damage to targets further away.",
  str_monster_ability_2920232 = "Vani can use Energy to strike from a distance.",
