  str_monster_passiveskill_desc_29140011 = "Vani recovers HP equal to 200% of the damage Bennuguardian deals.",
  str_monster_passiveskill_name_2920232 = "Tenacity",
  str_monster_passiveskill_desc_2920232 = "Increases DEF as HP decreases.",
  str_monster_passiveskill_name_2010715 = "Enfeeblement",
