  str_monster_passiveskill_name_20107152 = "Protection",
  str_monster_passiveskill_desc_20107152 = "If Deceptive Queen has Safeguard when taking action, grants 3 stacks of Safeguard to all other Eclipsites.",
  str_monster_passiveskill_name_2910801 = "Never Give Up",
  str_monster_passiveskill_desc_2910801 = "Desolate Monarch becomes stronger every time his HP bar is reduced to zero. Some Slumbering Eclipsites will also be awakened.",
  str_monster_passiveskill_name_29006411 = "Lock",
  str_monster_passiveskill_desc_29006411 = "Counters Aurorian Active Skills, dealing damage to the Aurorians and summoning Locked Tiles on the 4 tiles around them.",
  str_monster_passiveskill_name_29006611 = "Smash",
  str_monster_passiveskill_desc_29006611 = "Counters Aurorian Active Skills, randomly summoning damaged tiles.",
  str_monster_name_1502001 = "Forsaken: Anatoli",
  str_monster_name_1502001_en = "Anatoli",
  str_monster_desc_1502001 = "A calm and reliable intelligence officer of the Illumina Federation who makes unexpected complaints occasionally. No one knows whether these complaints are made intentionally or unintentionally.",
  str_monster_ability_1502001 = "Pulls over enemy units to control the battle situation more easily.",
  str_monster_name_1501761 = "Forsaken: Beretta",
  str_monster_name_1501761_en = "Beretta",
  str_monster_desc_1501761 = "A Lumopolis combat doctor was once saved by a doctor called John. Since then, she has made up her mind to become a good doctor.",
