  str_monster_passiveskill_name_1501761 = "Australis Counter",
  str_monster_passiveskill_desc_1501761 = "Counters Aurorian Active Skills, granting 1 Australis Spear mark. Deals damage 1 additional time when casting Australis Tempest.",
