  str_monster_name_5471001_en = "Reinhardt",
  str_monster_desc_5471001 = "Illumina Federation's veritable Grand Marshal. Not only is she courageous and skilled on the battlefield, she's also an honest and highly capable leader respected by all Illumina.",
  str_monster_ability_5471001 = "Possesses high ATK and can deal heavy damage to surrounding targets.",
  str_monster_desc_5471002 = "A combat droid modified by the Illumina Federation. Calibrated according to Reinhardt's specific attributes, it possesses some of her abilities.",
