  str_monster_name_2909801_en = "Spearhead: Rotbone Stinger",
  str_monster_desc_2909801 = "Once a battle Colossus who charged headfirst into the fray in the name of the Eclipse, it is now just a shattered pile of rubble, its last remaining threat lying in its tailbone.",
  str_monster_ability_2909801 = "Capable of dealing damage to targets in a large area and generating peripheral units that move in a cluster formation to block Aurorians.",
  str_monster_name_2005101 = "Periphery Provocant",
  str_monster_desc_2005101 = "Originally a part of Spearhead's tail, these pieces broke off one by one and scattered throughout the underground ruins.",
  str_monster_ability_2005101 = "Flying monsters controlled by a mysterious force, constantly form strange formations to launch close-range attacks on intruders.",
