  str_monster_name_70011421_en = "Forsaken: Figerald",
  str_monster_name_70011431 = "Forsaken: Ira",
  str_monster_name_70011431_en = "Forsaken: Ira",
  str_monster_passiveskill_name_2905201 = "Step Into the Void",
  str_monster_passiveskill_desc_2905201 = "The tiles Aurorians moved on will collapse accordingly. Tiles will not collapse in Aurora Time after Aurorians moved on them. Sanity drops by 30 when the scene collapses.",
  str_monster_name_2910101 = "David Porfirio",
  str_monster_name_2910101_en = "David Porfirio",
  str_monster_desc_2910101 = "Head of the Porfirio family. He is someone who likes dominating others and relentlessly pursues power by any means.",
  str_monster_ability_2910101 = "Uses different skills against Aurorians based on Sanity: Summons Necroservants or attacks to heal itself.",
  str_monster_passiveskill_name_29101011 = "Insanity",
  str_monster_passiveskill_desc_29101011 = "As Sanity drops, David Porfirio grows more frenzied, with lower DEF but higher ATK.",
  str_monster_passiveskill_name_29101012 = "Fear Deterrence",
  str_monster_passiveskill_desc_29101012 = "Take only 10% of the first damage from each Aurorian in each round.",
  str_monster_name_2005201 = "Necroservant",
  str_monster_desc_2005201 = "Miserable departed souls, forever deceived and confined. Now they wander, seeking fresh warm blood for their master.",
  str_monster_ability_2005201 = "Causes different damage effects to Aurorians based on Sanity: Drains Sanity or consumes HP.",
  str_monster_name_2910001 = "Syurton",
  str_monster_desc_2910001 = "A huge, tenacious siege vanguard. Even with limbs astray, it can devastate ground structures.",
  str_monster_ability_2910001 = "Can attack Aurorians with various body parts. Damaging any part of Syurton will harm it.",
  str_monster_name_2910001_en = "Syurton",
  str_monster_passiveskill_name_2910001 = "Sun-Rejector",
  str_monster_passiveskill_desc_2910001 = "Syurton's tail is immune to normal attacks and area damage.",
  str_monster_name_2909901 = "Stone Giant of the Ruins",
  str_monster_name_2909901_en = "Stone Giant of the Ruins",
  str_monster_desc_2909901 = "In the eyes of future Aurorians, extraordinary advanced technology may be seen as equivalent to magic, and in Fleur's eyes, the stone giant is akin to a mecha.",
  str_monster_ability_2909901 = "Possesses powerful healing abilities.",
  str_monster_passiveskill_name_2909901 = "Active Null",
  str_monster_passiveskill_desc_2909901 = "After every 3 Aurorian Active Skill casts, the Stone Giant of the Ruins counters, rendering the next Active Skill cast ineffective. This does not affect the Tactical System.",
  str_monster_name_70011451 = "Forsaken Dark Summoner",
  str_monster_name_70011451_en = "Forsaken Dark Summoner",
  str_monster_name_70011461 = "Forsaken Stone Giant of the Ruins",
  str_monster_name_70011461_en = "Forsaken Stone Giant of the Ruins",
  str_monster_name_700201901 = "Forsaken Regina",
  str_monster_name_700201901_en = "Forsaken Stone Giant of the Ruins",
  str_monster_desc_700201901 = "Her bold and uninhibited nature, as well as her impulsiveness, are the marks of a true rock n' roll soul! Her fierce musical style made her exceedingly popular within Rediesel Wrench, allowing her to not only inspire troops, but also lead them in a charge.",
  str_monster_ability_700201901 = "Cannot move, but excels at dealing large area damage and knocking enemies back.",
  str_monster_ability_70011451 = "Summons beacons and gains damage reduction based on the number of beacons around it. Its skills have a cross-shaped range attack and its chargeable skill's damage and range are based on the number of beacons.",
  str_monster_name_2910201 = "Stellandine: Prototype",
  str_monster_name_2910201_en = "Stellandine : Prototype",
  str_monster_desc_2910201 = "Cloaked in disguise, it sings and cries to lure in its prey. Once the disguise is shed, it defeats its enemies with violence and poison. All along, it fails to understand that love is suppressing one's nature.",
  str_monster_ability_2910201 = "Summons a large number of supporting Eclipsites, posing a threat to enemy units around itself.",
  str_monster_passiveskill_name_2910201 = "Whispers of the Deep Sea",
  str_monster_passiveskill_desc_2910201 = "At the start of each round, damage to Aurorians within 1 surrounding cluster is dealt with based on their current HP percentage.",
  str_monster_name_2005301 = "Salvo Gun",
  str_monster_desc_2005301 = "It's learning about Aurorians but having a hard time understanding when to fire the gun salute. All it wants is to whisper tenderly, but it ends up becoming a deep sea poison that corrodes everyone who approaches.",
  str_monster_ability_2005301 = "Poses a threat to enemy units around itself.",
  str_monster_name_2005401 = "Demand",
  str_monster_desc_2005401 = "Hungry for physical contact and love, it constantly approaches Aurorians. Afraid of getting hurt and being hated, it'd rather strike first.",
  str_monster_ability_2005401 = "When aware of a threat, Eclipsites are summoned for assistance.",
  str_monster_name_70020211 = "Forsaken : Stellandine",
  str_monster_name_70020211_en = "Forsaken : Stellandine",
  str_monster_name_39002111 = "Forsaken: Umbrahulk",
  str_monster_name_39002111_en = "The Forsaken: Umbrahulk",
  str_monster_ability_39002111 = "Its melee attack is accompanied with a knockback, and it has the ability to summon Pebbles for attacking. Hit targets will be knocked back. It can also launch a full-screen attack, and the damage dealt is determined by the number of Pebbles.",
  str_monster_name_2910301 = "Nepolis",
  str_monster_name_2910301_en = "Neapolis",
  str_monster_desc_2910301 = "The black lily of the Geminos Mirror—beloved sister of Nikinis, the fusion of spiritual power with the magic of the Northland Mirror, powerful yet elegant.",
  str_monster_ability_2910301 = "Nepolis excels at using mirrors to outmaneuver enemies, avoiding damage while delivering deadly strikes and cursing Aurorians using mirror creatures.",
  str_monster_passiveskill_name_2910301 = "Cursed Mirror",
  str_monster_passiveskill_desc_2910301 = "Every 3 rounds, Nepolis summons 1 mirror creature that self-destructs after 2 rounds, cursing a random Aurorian.",
